function usage(programName) {
  return `usage: ${programName} [-h] --a A --b B`;
}

function isNegativeNumberToken(token) {
  return /^-\d+(?:\.\d+)?(?:[eE][+-]?\d+)?$/.test(token);
}

function isMissingValueToken(token) {
  return token === '-h' || token.startsWith('--') || (token.startsWith('-') && !isNegativeNumberToken(token));
}

export function programNameFromArgv(argv) {
  const scriptPath = argv[1] || 'test13.mjs';
  return scriptPath.replace(/^.*[\\/]/, '');
}

export function helpText(programName) {
  return [
    usage(programName),
    '',
    'options:',
    '  -h, --help  show this help message and exit',
    '  --a A       instance (JSON string)',
    '  --b B       schema (JSON string)',
  ].join('\n');
}

export function errorText(programName, message) {
  return `${usage(programName)}\n${programName}: error: ${message}`;
}

function consumeValue(argv, index, optionName) {
  if (index + 1 >= argv.length || isMissingValueToken(argv[index + 1])) {
    return {
      nextIndex: index,
      error: `argument ${optionName}: expected one argument`,
    };
  }

  return {
    nextIndex: index + 1,
    value: argv[index + 1],
  };
}

export function parseArgs(argv, programName) {
  let a;
  let b;
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '-h' || token === '--help') {
      return { help: true };
    }

    if (token === '--') {
      extras.push(...argv.slice(index + 1));
      break;
    }

    if (token === '--a') {
      const consumed = consumeValue(argv, index, '--a');
      if (consumed.error) {
        return consumed;
      }
      a = consumed.value;
      index = consumed.nextIndex;
      continue;
    }

    if (token === '--b') {
      const consumed = consumeValue(argv, index, '--b');
      if (consumed.error) {
        return consumed;
      }
      b = consumed.value;
      index = consumed.nextIndex;
      continue;
    }

    if (token.startsWith('--a=')) {
      a = token.slice(4);
      continue;
    }

    if (token.startsWith('--b=')) {
      b = token.slice(4);
      continue;
    }

    extras.push(token);
  }

  if (extras.length > 0) {
    return {
      error: `unrecognized arguments: ${extras.join(' ')}`,
    };
  }

  const missing = [];
  if (a === undefined) {
    missing.push('--a');
  }
  if (b === undefined) {
    missing.push('--b');
  }

  if (missing.length > 0) {
    return {
      error: `the following arguments are required: ${missing.join(', ')}`,
    };
  }

  return {
    values: { a, b },
    programName,
  };
}

