import { errorText, helpText, parseArgs, programNameFromArgv } from './cli.mjs';
import { validatorFor } from './validator-core.mjs';

const programName = programNameFromArgv(process.argv);
const parsed = parseArgs(process.argv.slice(2), programName);

if (parsed.help) {
  process.stdout.write(`${helpText(programName)}\n`);
  process.exit(0);
}

if (parsed.error) {
  process.stderr.write(`${errorText(programName, parsed.error)}\n`);
  process.exit(2);
}

const instance = JSON.parse(parsed.values.a);
const schema = JSON.parse(parsed.values.b);

const ValidatorClass = validatorFor(schema);
const validator = new ValidatorClass(schema);

const result = validator.isValid(instance);
const errors = validator.iterErrors(instance);

console.log(ValidatorClass.name);
console.log(result ? 'True' : 'False');
console.log(String(errors.length));
